import 'dart:convert'; import 'dart:io'; import 'package:path_provider/path_provider.dart'; import '../db/database.dart';
class BackupService { Future<File> exportBackup() async { final db=await AppDatabase.instance.db; final tables=['profiles','categories','customers','work_entries','attachments','expenses','employees','attendance','payments','invoices','receipts','settings']; final out=<String,dynamic>{}; for(final t in tables) out[t]=await db.query(t); final dir=await getTemporaryDirectory(); final f=File('${dir.path}/work_time_backup_${DateTime.now().millisecondsSinceEpoch}.json'); await f.writeAsString(jsonEncode(out)); return f; } }
